const base="/home/axel/LeanAlgebraicGeometry-Horizon";
const qs=[
 ["tag", "rg -n --glob '*.lean' '0B7S|39\\.8\\.6|finite subsets.*group|finite set.*group.*affine' MainProjects/Algebraic-Jacobian-Challenge MainProjects/Algebraic-Jacobian-Challenge-Rebuild .lake-packages/mathlib/Mathlib"],
 ["all_group_affine_files", "rg -l --glob '*.lean' -i 'group scheme.*affine|affine.*group scheme|GrpObj.*affine|affine.*GrpObj' MainProjects/Algebraic-Jacobian-Challenge MainProjects/Algebraic-Jacobian-Challenge-Rebuild .lake-packages/mathlib/Mathlib/AlgebraicGeometry"],
 ["new_group_separated", "nl -ba MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/AbelianVariety/GroupSeparated.lean | sed -n '80,125p'"],
 ["old_group_separated", "nl -ba MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/PicEtSeparated.lean | sed -n '140,180p'"]
];
const rs=await Promise.all(qs.map(async([n,c])=>({n,...await tools.exec_command({cmd:c,workdir:base,yield_time_ms:30000,max_output_tokens:30000})})));
for(const r of rs) text(`--- ${r.n} ---\n${r.output}`);

const results = await Promise.all([
 tools.exec_command({cmd:"rg -n --glob '*.lean' 'IsHQuasiProjective|isHQuasiProjective|HQuasiProjective' AlgebraicJacobian | sed -n '1,320p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000}),
 tools.exec_command({cmd:"rg -n --glob '*.lean' 'IsHQuasiProjective|isHQuasiProjective|HQuasiProjective' AlgebraicJacobian | sed -n '1,360p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge",yield_time_ms:10000,max_output_tokens:30000}),
 tools.exec_command({cmd:"rg -n --glob '*.lean' 'gluedMap.*IsProjective|IsProjective.*gluedMap|glued.*IsHQuasiProjective|IsHQuasiProjective.*glued|gluedMap.*IsH|isProjective.*P\\.glued|P\\.glued.*isProjective' AlgebraicJacobian | sed -n '1,260p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000}),
 tools.exec_command({cmd:"rg -n --glob '*.lean' 'proper.*group.*projective|group.*proper.*projective|IsProjective.*GrpObj|GrpObj.*IsProjective|GroupScheme.*projective|quasi-projective.*group|quasi-projectivity.*group' AlgebraicJacobian | sed -n '1,360p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000})
]); for(let i=0;i<results.length;i++) text(`---${i+1}---\n${results[i].output}`);

const r = await tools.exec_command({
  cmd: "stat -c '%y %n' AlgebraicJacobian/Descent/GroupAffineOpen.lean .lake/build/lib/lean/AlgebraicJacobian/Descent/GroupAffineOpen.olean AlgebraicJacobian/Picard/Pic0FiniteStageOrbitAffine.lean .lake/build/lib/lean/AlgebraicJacobian/Picard/Pic0FiniteStageOrbitAffine.olean",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
text(r.output);

const results = await Promise.all([
 tools.exec_command({cmd:"stat -c '%n | mtime=%y | size=%s' AlgebraicJacobian/Descent/FiniteInAffine.lean .lake/build/lib/lean/AlgebraicJacobian/Descent/FiniteInAffine.olean AlgebraicJacobian/Picard/Pic0FiniteStageOrbitAffine.lean .lake/build/lib/lean/AlgebraicJacobian/Picard/Pic0FiniteStageOrbitAffine.olean 2>&1",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:10000}),
 tools.exec_command({cmd:"pgrep -af 'lake build AlgebraicJacobian.Picard.Pic0FiniteStageOrbitAffine' | sed -n '1,20p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:5000}),
 tools.exec_command({cmd:"rg -n --glob '*.lean' '\\bsorry\\b|sorryAx|axiom ' AlgebraicJacobian/Descent/FiniteInAffine.lean AlgebraicJacobian/Picard/Pic0FiniteStageOrbitAffine.lean",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:5000}),
 tools.exec_command({cmd:"\"$HORIZON_GIT\" log -1 --format='%H%n%B' 042292a818",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000})
]); for(let i=0;i<results.length;i++) text(`---${i+1}---\n${results[i].output}`);

const r = await tools.exec_command({
  cmd: "ps -o pid,etimes,stat,pcpu,pmem,cmd -p 1530458,1535203,1551932",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "rg -n --glob '*.lean' '^(def FiniteInAffine|theorem [A-Za-z0-9_\\.]*finiteInAffine|lemma [A-Za-z0-9_\\.]*finiteInAffine)' MainProjects/Algebraic-Jacobian-Challenge MainProjects/Algebraic-Jacobian-Challenge-Rebuild .lake-packages/mathlib/Mathlib",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 30000,
  max_output_tokens: 40000
});
text(r.output);
